package com.justfast.payments.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import jakarta.persistence.Version;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * One attempt to pay an order through the provider. Its id is generated by us before contacting the provider and is
 * used as the provider idempotency key and echoed back in webhooks, so retries never create a second session.
 */
@Entity
@Table(name = "payment_attempts")
public class PaymentAttempt {

    @Id
    @Column(length = 36)
    private String id;

    @Column(name = "order_id", nullable = false)
    private Long orderId;

    @Column(nullable = false)
    private String provider;

    @Column(name = "provider_session_id")
    private String providerSessionId;

    @Column(name = "checkout_url", length = 2048)
    private String checkoutUrl;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Column(nullable = false)
    private PaymentAttemptStatus status;

    @Column(name = "failure_reason")
    private String failureReason;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    protected PaymentAttempt() {
    }

    public PaymentAttempt(Long orderId, String provider, BigDecimal amount, String currency, Instant now) {
        this.id = UUID.randomUUID().toString();
        this.orderId = orderId;
        this.provider = provider;
        this.amount = amount;
        this.currency = currency;
        this.status = PaymentAttemptStatus.CREATED;
        this.createdAt = now;
        this.updatedAt = now;
    }

    public void sessionCreated(String sessionId, String url, Instant now) {
        if (status != PaymentAttemptStatus.CREATED) {
            return;
        }
        this.providerSessionId = sessionId;
        this.checkoutUrl = url;
        this.status = PaymentAttemptStatus.PENDING;
        this.updatedAt = now;
    }

    public void markSucceeded(Instant now) {
        this.status = PaymentAttemptStatus.SUCCEEDED;
        this.updatedAt = now;
    }

    public void markFailed(String reason, Instant now) {
        closeOpen(PaymentAttemptStatus.FAILED, reason, now);
    }

    public void markExpired(Instant now) {
        closeOpen(PaymentAttemptStatus.EXPIRED, null, now);
    }

    public void noteProblem(String reason, Instant now) {
        this.failureReason = reason;
        this.updatedAt = now;
    }

    private void closeOpen(PaymentAttemptStatus target, String reason, Instant now) {
        if (!status.isOpen()) {
            throw new IllegalStateException("Attempt " + id + " is already " + status);
        }
        this.status = target;
        this.failureReason = reason;
        this.updatedAt = now;
    }

    /** True when the reported amount and currency are exactly what we asked the provider to collect. */
    public boolean matches(BigDecimal reportedAmount, String reportedCurrency) {
        return reportedAmount != null && reportedCurrency != null
                && amount.compareTo(reportedAmount) == 0
                && currency.equalsIgnoreCase(reportedCurrency);
    }

    public boolean isOpen() {
        return status.isOpen();
    }

    public String getId() {
        return id;
    }

    public Long getOrderId() {
        return orderId;
    }

    public String getProvider() {
        return provider;
    }

    public String getProviderSessionId() {
        return providerSessionId;
    }

    public String getCheckoutUrl() {
        return checkoutUrl;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getCurrency() {
        return currency;
    }

    public PaymentAttemptStatus getStatus() {
        return status;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }
}
